mixin MTLArgumentEncoderAdapter {
  /// Lazily creates a native adapter for this Dart implementation.
  late final MTLArgumentEncoder asMTLArgumentEncoder =
      MTLArgumentEncoder$Builder.implementFrom(this as MTLArgumentEncoderSpec);

  /// Lazily creates a listener-backed native adapter for this Dart
  /// implementation.
  late final MTLArgumentEncoder asMTLArgumentEncoderListener =
      MTLArgumentEncoder$Builder.implementFromAsListener(
        this as MTLArgumentEncoderSpec,
      );

  /// Lazily creates a blocking-listener-backed native adapter for this Dart
  /// implementation.
  late final MTLArgumentEncoder asMTLArgumentEncoderBlocking =
      MTLArgumentEncoder$Builder.implementFromAsBlocking(
        this as MTLArgumentEncoderSpec,
      );
}

enum MTLArgumentType {
  MTLArgumentTypeBuffer(0),
  MTLArgumentTypeThreadgroupMemory(1),
  MTLArgumentTypeTexture(2),
  MTLArgumentTypeSampler(3),
  MTLArgumentTypeImageblockData(16),
  MTLArgumentTypeImageblock(17),
  MTLArgumentTypeVisibleFunctionTable(24),
  MTLArgumentTypePrimitiveAccelerationStructure(25),
  MTLArgumentTypeInstanceAccelerationStructure(26),
  MTLArgumentTypeIntersectionFunctionTable(27);

  final int value;
  const MTLArgumentType(this.value);

  static MTLArgumentType fromValue(int value) => switch (value) {
    0 => MTLArgumentTypeBuffer,
    1 => MTLArgumentTypeThreadgroupMemory,
    2 => MTLArgumentTypeTexture,
    3 => MTLArgumentTypeSampler,
    16 => MTLArgumentTypeImageblockData,
    17 => MTLArgumentTypeImageblock,
    24 => MTLArgumentTypeVisibleFunctionTable,
    25 => MTLArgumentTypePrimitiveAccelerationStructure,
    26 => MTLArgumentTypeInstanceAccelerationStructure,
    27 => MTLArgumentTypeIntersectionFunctionTable,
    _ => throw ArgumentError('Unknown value for MTLArgumentType: $value'),
  };
}

